<template>
  <div :class="isFull ? 'full' : 'log-editor'">
    <div class="toolbar">
      <div class="search-box">
        <el-input
          v-model="searchKeyword"
          @input="doSearch"
          @keydown.enter.native="next"
          ref="searchInput"
          placeholder="搜索"
          size="small"
        />
        <button @click="prev" :disabled="!total" class="nav-btn">↑</button>
        <button @click="next" :disabled="!total" class="nav-btn">↓</button>
        <span class="count">{{ index }}/{{ total }}</span>
      </div>
      <div>
        <el-button
          v-if="isStreamActive"
          title="暂停"
          icon="el-icon-video-pause"
          @click="stopStream"
        ></el-button>
        <el-button
          v-else
          title="恢复"
          icon="el-icon-video-play"
          @click="startStream"
        ></el-button>
        <el-button
          title="下载"
          icon="el-icon-download"
          @click="downloadLogTxt"
        ></el-button>
        <el-button
          title="清除"
          icon="el-icon-delete"
          @click="cleanLog"
        ></el-button>
        <el-button
          title="全屏"
          icon="el-icon-full-screen"
          @click="fullSreen"
          v-if="!isFull"
        ></el-button>
        <el-button
          title="退出"
          icon="el-icon-close"
          @click="isFull = false"
          v-else
        ></el-button>
      </div>
    </div>
    <div style="height: 70vh; width: 100%">
      <codemirror
        ref="cm"
        v-model="logContent"
        :options="cmOptions"
        @ready="onReady"
      />
    </div>
  </div>
</template>

<script>
import { codemirror } from "vue-codemirror";
import "codemirror/lib/codemirror.css";
import "codemirror/mode/javascript/javascript";

export default {
  name: "LogEditor",
  components: { codemirror },
  data() {
    return {
      logContent: "",
      searchKeyword: "",
      cm: null,
      matches: [],
      index: 0,
      total: 0,
      overlay: null,
      cmOptions: {
        mode: "application/json",
        lineNumbers: true,
        lineWrapping: true,
        readOnly: true,
        viewportMargin: Infinity,
        theme: "default",
        lineHeight: 1.6,
        fontSize: 14,
      },
      rawLogs: [],
      isFull: false,
      reader: null,
      isStreamActive: false,
      reconnectTimer: null,
    };
  },
  mounted() {
    this.setStyle();
    this.startStream();
    document.addEventListener("keydown", this.handleCtrlF);
  },
  beforeDestroy() {
    document.removeEventListener("keydown", this.handleCtrlF);
    const elMain = document.querySelector(".el-main");
    if (elMain) {
      elMain.style.padding = "20px";
      elMain.style.overflow = "auto";
    }
    this.stopStream();

    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
  },
  methods: {
    // 关闭流
    stopStream() {
      this.isStreamActive = false; // 立即关闭循环开关
      console.log("SSE 流已手动暂停");

      if (this.reader) {
        this.reader.cancel().catch(() => {});
        this.reader = null;
      }

      // 清除重连定时器，防止自动重连
      if (this.reconnectTimer) {
        clearTimeout(this.reconnectTimer);
        this.reconnectTimer = null;
      }
    },

    // 清空日志
    cleanLog() {
      this.rawLogs = [];
      this.logContent = "";
      this.doSearch();
    },

    // 下载日志
    downloadLogTxt() {
      if (!this.rawLogs.length) {
        this.$message.warning("暂无日志可下载");
        return;
      }

      const logText = this.rawLogs.join("\n");
      const blob = new Blob([logText], {
        type: "text/plain;charset=utf-8",
      });

      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      const date = new Date().toLocaleString().replace(/[/:\s]/g, "-");
      a.download = `系统日志_${date}.txt`;

      a.click();
      setTimeout(() => URL.revokeObjectURL(url), 100);
    },

    // 启动SSE流
    async startStream() {
      // 如果已经在运行，直接返回
      if (this.isStreamActive) return;

      this.stopStream();
      this.isStreamActive = true;

      const token = localStorage.getItem("token");

      try {
        const response = await fetch("/api/sys/log", {
          method: "GET",
          headers: {
            token: token,
            Accept: "text/event-stream",
            "Cache-Control": "no-cache",
            Connection: "keep-alive",
          },
        });

        if (!response.ok) {
          throw new Error(`请求失败: ${response.status}`);
        }

        this.reader = response.body.getReader();
        const decoder = new TextDecoder();

        while (this.isStreamActive) {
          const { done, value } = await this.reader.read();

          if (!this.isStreamActive || done) break;

          const chunk = decoder.decode(value, { stream: true });
          const lines = chunk.split("\n").filter((line) => line.trim());

          for (const line of lines) {
            if (!this.isStreamActive) break;

            if (line.startsWith("data: ")) {
              const jsonStr = line.replace("data: ", "");
              try {
                const data = JSON.parse(jsonStr);
                this.rawLogs.push(data.data);
              } catch (e) {
                this.rawLogs.push(jsonStr);
              }
              this.logContent = this.rawLogs.join("\n");

              this.$nextTick(() => {
                if (this.cm) {
                  const lineCount = this.cm.lineCount();
                  this.cm.setCursor(lineCount - 1);
                  this.cm.scrollIntoView({ line: lineCount - 1, ch: 0 });
                }
              });
            }
          }
        }
      } catch (err) {
        console.error("流请求失败:", err);
      } finally {
        // 只有非手动关闭才重连
        if (this.isStreamActive && !this._isBeingDestroyed) {
          this.reconnectTimer = setTimeout(() => {
            this.startStream();
          }, 3000);
        }
        this.isStreamActive = false;
      }
    },

    // 全屏
    fullSreen() {
      this.isFull = true;
    },

    onReady(cm) {
      this.cm = cm;
    },

    handleCtrlF(e) {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "f") {
        e.preventDefault();
        this.$refs.searchInput?.focus();
      }
    },

    doSearch() {
      const key = this.searchKeyword.trim();
      if (this.overlay) {
        this.cm?.removeOverlay(this.overlay);
        this.overlay = null;
      }

      if (!key || !this.cm) {
        this.matches = [];
        this.total = 0;
        this.index = 0;
        return;
      }

      this.overlay = {
        token: (stream) => {
          if (stream.match(new RegExp(`(${key})`, "i"))) {
            return "search-hl";
          }
          stream.next();
          return null;
        },
      };
      this.cm.addOverlay(this.overlay);

      const text = this.cm.getValue();
      const lines = text.split("\n");
      const list = [];
      const regex = new RegExp(key, "gi");

      lines.forEach((lineText, lineNum) => {
        let match;
        while ((match = regex.exec(lineText)) !== null) {
          list.push({
            line: lineNum,
            ch: match.index,
            len: match[0].length,
          });
        }
      });

      this.matches = list;
      this.total = list.length;

      if (this.total > 0) {
        this.index = 1;
        this.jump(0);
      }
    },

    jump(i) {
      const m = this.matches[i];
      if (!m || !this.cm) return;
      this.cm.setSelection(
        { line: m.line, ch: m.ch },
        { line: m.line, ch: m.ch + m.len }
      );
      this.cm.scrollIntoView({ line: m.line, ch: 0 }, 100);
    },

    prev() {
      if (this.total === 0) return;
      let i = this.index - 2;
      if (i < 0) i = this.total - 1;
      this.index = i + 1;
      this.jump(i);
    },

    next() {
      if (this.total === 0) return;
      let i = this.index;
      if (i >= this.total) i = 0;
      this.index = i + 1;
      this.jump(i);
    },
    setStyle() {
      const elMain = document.querySelector(".el-main");
      if (elMain) {
        elMain.style.overflow = "hidden";
      }
    },
  },
};
</script>

<style scoped>
.log-editor {
  width: 100%;
  display: flex;
  flex-direction: column;
  background: #ffffff;
}
.full {
  width: 100%;
  display: flex;
  flex-direction: column;
  background: #ffffff;
  position: absolute;
  top: 0;
  bottom: 0;
  right: 0;
  left: 0;
  z-index: 99999;
}

.toolbar {
  z-index: 9999 !important;
  background: #f9fafb !important;
  display: flex;
  justify-content: space-between;
  padding: 8px 12px;
  border-bottom: 1px solid #e5e7eb;
  gap: 8px;
}

.search-box {
  display: flex;
  align-items: center;
  gap: 4px;
}
.nav-btn {
  width: 28px;
  height: 28px;
  border: 1px solid #d1d5db;
  background: #ffffff;
  cursor: pointer;
  border-radius: 4px;
  font-size: 14px;
  line-height: 26px;
  text-align: center;
  padding: 0;
}
.nav-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.count {
  font-size: 12px;
  color: #6b7280;
  min-width: 50px;
  margin-left: 4px;
}

::v-deep .CodeMirror {
  flex: 1;
  height: 100% !important;
  font-family: "Consolas", "Monaco", "Courier New", monospace;
  font-size: 14px;
  line-height: 1.6 !important;
  background: #ffffff;
  color: #111827;
  width: 100% !important;
}
::v-deep .CodeMirror-scroll{
  width: 100% !important;
}
::v-deep .CodeMirror-lines {
  padding: 4px 0;
}
::v-deep .CodeMirror-line {
  padding: 2px 0;
  line-height: 1.6 !important;
}
::v-deep .CodeMirror-linenumber {
  color: #6b7280;
  background: #ffffff;
  padding: 0 8px 0 4px;
  min-width: 30px;
  text-align: right;
}
::v-deep .CodeMirror-gutters {
  background: #ffffff;
  border-right: 1px solid #e5e7eb;
}
::v-deep .CodeMirror-activeline-background {
  background: #f3f4f6;
}

::v-deep .cm-search-hl {
  background: #facc15 !important;
  color: #000000 !important;
  padding: 1px 2px;
  border-radius: 2px;
}
::v-deep .CodeMirror-selected {
  background: #f97316 !important;
  color: #ffffff !important;
}
::v-deep .vue-codemirror {
  height: 100%;
}
::v-deep .el-button {
  padding: 4px !important;
  font-size: 18px !important;
}
</style>
